import { z } from 'zod';
import {
  DESCRIPTION_MAX_LENGTH,
  REFERENCE_ID_MAX_LENGTH,
  TRANSACTION_TYPES,
} from './transaction.model';

export const MAX_PAGE_SIZE = 100;

/** Reference IDs with this prefix are generated by the transfer feature and reserved for it. */
export const TRANSFER_REFERENCE_PREFIX = 'transfer:';

/** Positive integer in minor currency units (e.g. paise). Zod's int() also enforces safe integers. */
export const amountSchema = z
  .number({ error: 'Amount must be a number.' })
  .int('Amount must be an integer number of minor currency units.')
  .positive('Amount must be greater than zero.');

export const referenceIdSchema = z
  .string({ error: 'Reference ID is required and must be a string.' })
  .trim()
  .min(1, 'Reference ID must not be blank.')
  .max(
    REFERENCE_ID_MAX_LENGTH,
    `Reference ID must be at most ${REFERENCE_ID_MAX_LENGTH} characters.`,
  );

export const descriptionSchema = z
  .string({ error: 'Description must be a string.' })
  .trim()
  .max(DESCRIPTION_MAX_LENGTH, `Description must be at most ${DESCRIPTION_MAX_LENGTH} characters.`)
  .default('');

export const createTransactionSchema = z.object({
  type: z.enum(TRANSACTION_TYPES, { error: "Type must be either 'credit' or 'debit'." }),
  amount: amountSchema,
  referenceId: referenceIdSchema.refine(
    (value) => !value.toLowerCase().startsWith(TRANSFER_REFERENCE_PREFIX),
    `Reference IDs starting with "${TRANSFER_REFERENCE_PREFIX}" are reserved for transfers.`,
  ),
  description: descriptionSchema,
});

export type CreateTransactionInput = z.infer<typeof createTransactionSchema>;

/** Query-string integer: digits only (rejects "1.5", "-1", "1e3", "abc"), then range-checked. */
const positiveIntQuery = (name: string, defaultValue: number, max: number) =>
  z
    .string({ error: `${name} must be a single positive integer.` })
    .regex(/^\d+$/, `${name} must be a positive integer.`)
    .transform(Number)
    .pipe(
      z
        .number()
        .int(`${name} is too large.`)
        .min(1, `${name} must be at least 1.`)
        .max(max, `${name} must be at most ${max}.`),
    )
    .default(defaultValue);

export const paginationQuerySchema = z.object({
  page: positiveIntQuery('page', 1, Number.MAX_SAFE_INTEGER),
  limit: positiveIntQuery('limit', 10, MAX_PAGE_SIZE),
});

export type PaginationQuery = z.infer<typeof paginationQuerySchema>;
